-- Disable triggers
SET session_replication_role = 'replica';

-- tbl_online_sales
DELETE FROM tbl_online_sales;

-- tbl_onlinesales_items
DELETE FROM tbl_onlinesales_items;

-- Re-enable triggers
SET session_replication_role = 'origin';

-- Sync sequences
SELECT setval('tbl_online_sales_id_seq', (SELECT MAX(id) FROM tbl_online_sales));
SELECT setval('tbl_onlinesales_items_id_seq', (SELECT MAX(id) FROM tbl_onlinesales_items));
